// 시험 전용 mock. 실제 state 구현이 아니며 저장하지 않는다.
return $input.all().map((item) => {
  const r = item.json;
  const bump = (ref) => ({ ...ref, state_revision: ref.state_revision + 1 });
  if (r.op === 'begin') {
    const id = r.request.request_id;
    const prior = r.request.case_ref === 'case-prior-2' ? 2 : 0;
    return { json: { request_id: id, mode: 'proceed', state_ref: { scope: r.scope, request_id: id, owner_id: r.actor.id, input_hash: r.input_hash, execution_id: r.execution_id, state_revision: 0 }, support: { case_id: r.request.case_ref ?? `case-${id}`, owner_id: r.actor.id, ticket_id: prior ? 'T-MOCK-PRIOR' : null, first_request_id: id, attempt: prior, version: null, status: 'received' }, facts: { summary: '', reported: [], confirmed: [], attempted_actions: [], missing: [], uncertainties: [], evidence_refs: [] }, response: null, http_status: 200, error_code: null } };
  }
  if (r.op === 'prepare') return { json: { request_id: r.state_ref.request_id, ok: true, skipped: false, state_ref: bump(r.state_ref), error_code: null } };
  if (r.op === 'save') return { json: { request_id: r.state_ref.request_id, ok: true, state_ref: bump(r.state_ref), error_code: null, recovery: null } };
  if (r.op === 'fail') return { json: { request_id: r.state_ref?.request_id ?? null, ok: true, skipped: !r.state_ref, state_ref: r.state_ref ? bump(r.state_ref) : null, error_code: null } };
  return { json: { request_id: null, ok: false, skipped: false, state_ref: null, error_code: 'mock_unknown_op' } };
});
